Consider the following POSIX C program (headers omitted).

```c
int x = 0;

void *worker(void *arg) {
    x = 10;
    return NULL;
}

int main(void) {
    pthread_t t;
    pthread_create(&t, NULL, worker, NULL);
    pthread_join(t, NULL);
    printf("%d\n", x);
    return 0;
}
```

What does the program print?

Consider the following POSIX C program (headers omitted; all calls succeed).

```c
int x = 0;

void *add5(void *arg) { x += 5; return NULL; }

int main(void) {
    if (fork() == 0) {          /* child */
        x += 1;
        exit(0);
    }
    wait(NULL);                 /* parent waits for child */
    pthread_t t;
    pthread_create(&t, NULL, add5, NULL);
    pthread_join(t, NULL);
    printf("%d\n", x);
    return 0;
}
```

What does the parent print?

Consider the following POSIX C program (headers omitted; all calls succeed, `m` is a properly initialised mutex).

```c
int g = 0;
pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;

void *work(void *arg) {
    int local = 0;
    static int s = 0;
    pthread_mutex_lock(&m);
    local++;
    s++;
    g += local + s;
    pthread_mutex_unlock(&m);
    return NULL;
}

int main(void) {
    pthread_t t[3];
    for (int i = 0; i < 3; i++) pthread_create(&t[i], NULL, work, NULL);
    for (int i = 0; i < 3; i++) pthread_join(t[i], NULL);
    printf("%d\n", g);
    return 0;
}
```

What value is printed?

Consider the following POSIX C program (headers omitted). Assume all calls succeed, `stdout` is **unbuffered** (every `printf` is written immediately), and `fork()` has standard POSIX semantics.

```c
void *f(void *arg) {
    if (fork() && fork())
        printf("p\n");
    printf("x\n");
    return NULL;
}

int main(void) {
    pthread_t t1, t2;
    fork();
    pthread_create(&t1, NULL, f, NULL);
    pthread_create(&t2, NULL, f, NULL);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    printf("y\n");
    return 0;
}
```

How many lines are printed in total, counting the output of all processes?

Consider the following POSIX C program (headers omitted). All calls succeed, `stdout` is unbuffered, and `fork()` has standard POSIX semantics. The statement `x = x + 1` compiles to a separate load of `x` into a register, an add, and a store back to `x`; a thread may be preempted between any two of these steps, and threads may run in any interleaving.

```c
int x = 0;

void *inc(void *arg) {
    x = x + 1;
    return NULL;
}

int main(void) {
    pthread_t t1, t2;
    pthread_create(&t1, NULL, inc, NULL);
    if (fork() == 0) {               /* child */
        x = x + 10;
        printf("child %d\n", x);
        exit(0);
    }
    pthread_create(&t2, NULL, inc, NULL);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    wait(NULL);
    printf("parent %d\n", x);
    return 0;
}
```

Which of the following combinations of the two output lines are possible in some execution?
